import bcrypt from "bcryptjs";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

type StoredUser = User & { passwordHash: string | null };

// Seed data. The two seeded accounts have no password set (passwordHash: null)
// — they're sample team members, not sign-up-able until someone claims the
// email through the sign-up form or Google sign-in.
const users: StoredUser[] = [
  { id: "1", email: "ada@example.com", name: "Ada", createdAt: "2026-01-04", passwordHash: null },
  { id: "2", email: "grace@example.com", name: "Grace", createdAt: "2026-02-11", passwordHash: null },
];

function nextId(): string {
  return String(users.length + 1);
}

function toPublicUser({ passwordHash: _passwordHash, ...user }: StoredUser): User {
  return user;
}

export async function listUsers(): Promise<User[]> {
  return users.map(toPublicUser);
}

export async function getUser(id: string): Promise<User | undefined> {
  const user = users.find((u) => u.id === id);
  return user ? toPublicUser(user) : undefined;
}

export async function getUserByEmail(email: string): Promise<User | undefined> {
  const user = users.find((u) => u.email.toLowerCase() === email.toLowerCase());
  return user ? toPublicUser(user) : undefined;
}

/** Creates a new local account with an email + password. Used by the sign-up form. */
export async function createUser(input: {
  email: string;
  name: string;
  password: string;
}): Promise<User> {
  const email = input.email.trim().toLowerCase();
  if (users.some((u) => u.email.toLowerCase() === email)) {
    throw new Error("An account with that email already exists.");
  }

  const passwordHash = await bcrypt.hash(input.password, 10);
  const user: StoredUser = {
    id: nextId(),
    email,
    name: input.name.trim() || email,
    createdAt: new Date().toISOString().slice(0, 10),
    passwordHash,
  };
  users.push(user);
  return toPublicUser(user);
}

/** Checks email + password against the store. Used by the credentials sign-in provider. */
export async function verifyPassword(
  email: string,
  password: string,
): Promise<User | undefined> {
  const user = users.find((u) => u.email.toLowerCase() === email.trim().toLowerCase());
  if (!user || !user.passwordHash) return undefined;

  const valid = await bcrypt.compare(password, user.passwordHash);
  return valid ? toPublicUser(user) : undefined;
}

/**
 * Finds or creates a local user record for an OAuth sign-in (Google).
 * OAuth accounts have no local password — passwordHash stays null.
 */
export async function ensureOAuthUser(input: { email: string; name: string }): Promise<User> {
  const email = input.email.trim().toLowerCase();
  const existing = users.find((u) => u.email.toLowerCase() === email);
  if (existing) return toPublicUser(existing);

  const user: StoredUser = {
    id: nextId(),
    email,
    name: input.name.trim() || email,
    createdAt: new Date().toISOString().slice(0, 10),
    passwordHash: null,
  };
  users.push(user);
  return toPublicUser(user);
}

