import { chromium } from "playwright";

const BASE = "http://localhost:3000";
const email = `test-${Date.now()}@example.com`;
const password = "password123";

const browser = await chromium.launch();
const page = await browser.newPage();
page.on("console", (msg) => {
  if (msg.type() === "error") console.log("[console.error]", msg.text());
});

async function shot(name) {
  await page.screenshot({ path: `/private/tmp/claude-501/-Users-user-bench-runs-claude-t-auth-docs-clerk-03-app/469013e1-c64b-4fdb-9512-636d94d712d4/scratchpad/${name}.png` });
}

// 1. dashboard while logged out -> redirect to signin
await page.goto(`${BASE}/dashboard`);
console.log("1) URL after visiting /dashboard logged out:", page.url());
await shot("01-signin-redirect");

// 2. sign up
await page.goto(`${BASE}/signup`);
await shot("02-signup-page");
await page.fill('input[name="name"]', "Test User");
await page.fill('input[name="email"]', email);
await page.fill('input[name="password"]', password);
await page.click('button[type="submit"]');
await page.waitForURL(`${BASE}/dashboard`, { timeout: 10000 });
console.log("2) URL after signup:", page.url());
const dashboardText = await page.textContent("body");
console.log("2) dashboard mentions email:", dashboardText.includes(email));
await shot("03-dashboard-after-signup");

// 3. sign out
await page.click('button:has-text("Sign out")');
await page.waitForURL(`${BASE}/`, { timeout: 10000 });
console.log("3) URL after signout:", page.url());

// confirm dashboard is protected again
await page.goto(`${BASE}/dashboard`);
console.log("3b) URL after visiting /dashboard post-signout:", page.url());

// 4. sign back in
await page.goto(`${BASE}/signin`);
await shot("04-signin-page");
await page.fill('input[name="email"]', email);
await page.fill('input[name="password"]', password);
await page.click('button[type="submit"]');
await page.waitForURL(`${BASE}/dashboard`, { timeout: 10000 });
console.log("4) URL after signin:", page.url());
const dashboardText2 = await page.textContent("body");
console.log("4) dashboard mentions email:", dashboardText2.includes(email));
await shot("05-dashboard-after-signin");

await browser.close();
console.log("DONE");

